const GRADES_META = {
  primary: { label:'🏫 ابتدائي',         sub:'الصف الأول — السادس' },
  middle:  { label:'📚 إعدادي / متوسط', sub:'الصف السابع — التاسع' },
  high:    { label:'🎓 ثانوي',           sub:'الصف العاشر — الثاني عشر' },
};

function mkSubj(name, icon, color, ...topics) {
  return { name, icon, color, topics };
}

const S_MATH='#3B82F6', S_PHY='#F59E0B',  S_CHEM='#10B981', S_BIO='#EC4899',
      S_AR='#8B5CF6',   S_EN='#F97316',   S_ISL='#84CC16',  S_HIST='#6366F1',
      S_GEO='#0EA5E9',  S_SCI='#06B6D4',  S_FR='#003189',   S_PHIL='#64748B',
      S_COMP='#8B5CF6', S_SOC='#A855F7';

/* Cambridge pathway (Primary 1–6, Lower Secondary 7–9): the non-core subjects every
   Cambridge school timetables alongside English / Maths / Science / Computing.
   Topics scale with the stage so a Year 2 child and a Year 9 student don't see the same list. */
function _camExtras(stage) {
  const b = stage <= 2 ? 0 : stage <= 4 ? 1 : stage <= 6 ? 2 : 3;
  const pick = arr => arr[b];
  return [
    mkSubj('English as a Second Language','🗣️',S_EN, ...pick([
      ['Everyday words: family, school, home, food, animals','Listening and following simple instructions','Speaking: greetings, questions and short answers','Reading picture books and short sentences','Writing words and simple sentences'],
      ['Vocabulary for daily routines, hobbies and places','Present and past simple','Question forms and short conversations','Reading short stories and factual texts for detail','Writing short paragraphs, messages and descriptions'],
      ['Tenses: present, past, future and continuous forms','Comparatives, superlatives and modal verbs','Listening for gist and detail','Reading fiction and non-fiction: main idea and inference','Writing emails, stories and short reports'],
      ['Grammar: perfect tenses, conditionals, passive voice, reported speech','Vocabulary building: topics, collocations, word families','Listening to talks and conversations for opinion and detail','Reading longer texts: skimming, scanning, inference','Writing: emails, articles, reviews and opinion essays','Speaking: presentations and discussions'],
    ])),
    mkSubj('Global Perspectives','🌍',S_GEO, ...pick([
      ['Keeping healthy','Sharing planet Earth','Our families and communities','Skills: asking questions and sharing ideas'],
      ['Water, food and agriculture','Caring for the environment','Values and beliefs','Skills: research, collaboration and communication'],
      ['Climate change','Trade and aid','Technology in our lives','Conflict and peace','Skills: research, analysis, evaluation and reflection'],
      ['Sustainable living and climate change','Digital world and technology','Migration and changing communities','Trade, aid and globalisation','Health and wellbeing','Skills: research, analysis, evaluation, reflection, collaboration, communication'],
    ])),
    mkSubj('Arabic','📖',S_AR, ...pick([
      ['الحروف الهجائية وأصواتها','الحركات والمدود','قراءة كلمات وجمل قصيرة','كتابة الحروف والكلمات','الاستماع والمحادثة البسيطة'],
      ['القراءة الجهرية والفهم','الجملة الاسمية والجملة الفعلية','المفرد والمثنى والجمع','الإملاء: التاء المربوطة والمفتوحة واللام الشمسية والقمرية','كتابة فقرة قصيرة'],
      ['فهم النصوص الأدبية والمعلوماتية','النحو: المبتدأ والخبر، الفاعل والمفعول به، كان وإنّ','الإملاء: الهمزات والألف اللينة','التعبير الكتابي: القصة والرسالة والوصف','حفظ النصوص الشعرية وتذوقها'],
      ['تحليل النصوص الأدبية والصور البلاغية','النحو: الأفعال الخمسة، الممنوع من الصرف، الحال والتمييز، الأساليب','الصرف: الميزان الصرفي والمشتقات','البلاغة: التشبيه والاستعارة والكناية','التعبير: المقال والتقرير والقصة','الإملاء وعلامات الترقيم'],
    ])),
    mkSubj('Islamic Studies / Religious Education','🕌',S_ISL, ...pick([
      ['أركان الإسلام والإيمان','قصار السور وحفظها','الوضوء والصلاة','الآداب الإسلامية اليومية','قصص الأنبياء للأطفال'],
      ['حفظ وتفسير سور من جزء عمّ','السيرة النبوية: المولد والنشأة','الصلاة والصيام','الأخلاق: الصدق والأمانة وبر الوالدين','قصص الأنبياء'],
      ['التلاوة والتجويد: أحكام النون الساكنة والتنوين','السيرة: الهجرة وبناء المجتمع في المدينة','الحديث الشريف وآدابه','الزكاة والحج','الأخلاق والمعاملات'],
      ['تفسير آيات مختارة وأسباب النزول','الحديث الشريف ومصطلحاته الأساسية','العقيدة: الإيمان بالله والرسل واليوم الآخر','الفقه: العبادات والمعاملات','السيرة والخلفاء الراشدون','القيم والأخلاق في الحياة المعاصرة'],
    ])),
    mkSubj('Art & Design','🎨',S_SOC, ...pick([
      ['Colours: primary and secondary','Drawing lines and shapes','Collage and printing','Modelling with clay and dough'],
      ['Colour mixing and tone','Pattern and texture','Drawing from observation','Artists and art from different cultures'],
      ['Perspective and proportion','Painting techniques and mixed media','3D sculpture and design','Studying famous artists and art movements'],
      ['Observational drawing: tone, line, perspective','Painting, printmaking and mixed media','3D design and sculpture','Graphic and digital design','Art history and critical analysis','Developing a sketchbook and final piece'],
    ])),
    mkSubj('Music','🎵',S_SOC, ...pick([
      ['Singing songs and rhymes','Beat and rhythm','Loud and quiet, high and low','Playing percussion instruments'],
      ['Rhythm patterns and simple notation','Singing in groups and rounds','Instruments of the orchestra','Listening to music from different cultures'],
      ['Reading staff notation','Melody, harmony and texture','Composing short pieces','Music from around the world'],
      ['Music theory: notation, scales, keys, chords','Composing and arranging','Performing solo and in ensembles','Listening: Western classical periods and world music','Music technology basics'],
    ])),
    mkSubj('Physical Education & Wellbeing','⚽',S_BIO, ...pick([
      ['Running, jumping and throwing','Balance and coordination','Team games and taking turns','Feelings and friendships'],
      ['Ball skills and simple team games','Gymnastics and dance','Healthy eating and exercise','Managing emotions and being kind'],
      ['Athletics, swimming and team sports','Fitness and the body during exercise','Fair play and teamwork','Resilience, self-esteem and online wellbeing'],
      ['Team sports: rules, tactics and skills','Fitness components and training methods','Health: diet, sleep and mental wellbeing','Leadership, teamwork and resilience'],
    ])),
  ];
}

/* US schools: the specials / electives every grade has besides the four core subjects. */
function _usExtras(g) {
  const b = g <= 2 ? 0 : g <= 5 ? 1 : 2;
  const pick = arr => arr[b];
  return [
    mkSubj('Computer Science & Technology','💻',S_COMP, ...pick([
      ['Using a computer, tablet and mouse','Unplugged coding: sequences and patterns','Block coding (ScratchJr, Code.org)','Staying safe online'],
      ['Block-based coding: loops, events and conditionals (Scratch)','Keyboarding and digital documents','How the internet works','Digital citizenship and online safety','Collecting and graphing data'],
      ['Programming: Scratch to Python — variables, loops, functions','Web basics: HTML & CSS','Data and spreadsheets','Networks, the internet and cybersecurity','Digital citizenship and AI literacy'],
    ])),
    mkSubj('Spanish (World Language)','🇪🇸',S_FR, ...pick([
      ['Greetings, colours and numbers','Family, animals and food words','Songs and simple conversations'],
      ['Everyday vocabulary: school, home, weather, time','Present tense of common verbs','Asking and answering questions','Hispanic cultures and traditions'],
      ['Present, past (preterite) and near future','Gender, articles and adjective agreement','Reading and writing short texts','Conversations on daily life, travel and hobbies','Culture of Spanish-speaking countries'],
    ])),
    mkSubj('Art','🎨',S_SOC, ...pick([
      ['Colours, lines and shapes','Drawing and painting','Collage, clay and crafts'],
      ['Elements of art: line, shape, colour, texture, form','Drawing from observation','Artists and art history','Printmaking and sculpture'],
      ['Principles of design: balance, contrast, emphasis','Drawing, painting and digital art','Art history and critique','3D art and ceramics'],
    ])),
    mkSubj('Music','🎵',S_SOC, ...pick([
      ['Singing and rhythm games','Steady beat and tempo','Classroom instruments'],
      ['Reading rhythms and notes','Recorder and ukulele basics','Music of different cultures','Composers and the orchestra'],
      ['Band, choir or orchestra skills','Music theory: scales, keys, chords','Composing and music technology','Music history and genres'],
    ])),
    mkSubj('Health & Physical Education','⚽',S_BIO, ...pick([
      ['Movement skills: running, jumping, throwing, catching','Healthy food and sleep','Personal safety and hygiene','Feelings and making friends'],
      ['Team games and fitness','Nutrition and the food groups','The human body and growth','Safety, first aid and emotional health'],
      ['Fitness components and personal fitness plans','Team and individual sports','Nutrition and healthy choices','Puberty, mental health and substance-abuse prevention','First aid and safety'],
    ])),
  ];
}

/* shared subject builders for curricula with similar structures */
function _primarySubjects(countryHistory) {
  return [
    mkSubj('الرياضيات','🔢',S_MATH,'الأعداد والعمليات الأساسية','الجمع والطرح','الضرب والقسمة','الكسور العادية','القياس والوحدات','الأشكال الهندسية','المسائل الحياتية'),
    mkSubj('اللغة العربية','📜',S_AR,'الحروف والقراءة','القراءة والاستيعاب','النحو الأساسي','الإملاء والكتابة','التعبير الشفهي والكتابي','المحفوظات والأناشيد'),
    mkSubj('العلوم','🔬',S_SCI,'الكائنات الحية','جسم الإنسان','الطاقة وأشكالها','المادة وخواصها','الأرض والفضاء','البيئة والطبيعة'),
    mkSubj('الدراسات الاجتماعية','🌍',S_HIST,...countryHistory),
    mkSubj('التربية الإسلامية','☪️',S_ISL,'القرآن الكريم وتجويده','الأحاديث النبوية','أركان الإسلام','السلوك والأخلاق','السيرة النبوية'),
    mkSubj('اللغة الإنجليزية','🗣️',S_EN,'Alphabet & Phonics','Basic Vocabulary','Simple Sentences','Reading Passages','Writing Practice'),
  ];
}

