const tplLoading = () => `
<div style="display:flex;flex-direction:column;align-items:center;justify-content:center;height:100vh;gap:20px;
            background:radial-gradient(ellipse at 50% 40%,#3B82F618 0%,transparent 60%),var(--bg)">
  <div style="position:relative">
    <div style="font-size:72px;animation:pulse-logo 2s ease-in-out infinite">🎓</div>
    <div style="position:absolute;inset:-8px;border-radius:50%;border:2px solid #3B82F644;animation:spin-ring 2s linear infinite"></div>
  </div>
  <div style="font-size:26px;font-weight:900;color:var(--primary);letter-spacing:-0.5px">${S.lang==='en'?'Ostazzi':'أستاذي'}</div>
  <div style="font-size:13px;color:var(--text-muted)" id="loading-msg">${S.lang==='en'?'Loading…':'جارٍ التحميل...'}</div>
  <div style="width:200px;height:3px;background:var(--border);border-radius:999px;overflow:hidden">
    <div style="height:100%;background:linear-gradient(90deg,var(--primary),#8B5CF6);border-radius:999px;animation:loading-bar 1.8s ease-in-out infinite"></div>
  </div>
</div>
<style>
@keyframes pulse-logo{0%,100%{transform:scale(1)}50%{transform:scale(1.08)}}
@keyframes spin-ring{to{transform:rotate(360deg)}}
@keyframes loading-bar{0%{width:0%;margin-right:100%}50%{width:60%;margin-right:20%}100%{width:0%;margin-right:0%;margin-left:100%}}
</style>`;

/* ════════════════════════════════════════════════════════════
   LANDING / MARKETING PAGE (shown to logged-out visitors)
   ════════════════════════════════════════════════════════════ */
function goRegister(level) {
  if (level) { try { localStorage.setItem('signup_level', level); } catch (_) {} }
  // analytics: track the "Start Learning" intent
  try { if (window.gtag) gtag('event', 'start_learning', { level: level || 'cta' }); } catch (_) {}
  try { if (window.clarity) clarity('event', 'start_learning'); } catch (_) {}
  S.screen = 'register'; render();
}
function goSignin() { S.screen = 'signin'; render(); }
function goParent() { S.screen = 'parent'; render(); }

/* ── Parent Dashboard (read-only child progress via consent code) ── */
function tplParent() {
  const L = (ar, en) => S.lang === 'en' ? en : ar;
  return `
<div class="auth-screen">
  <div class="auth-card" style="max-width:460px">
    <div style="position:absolute;top:16px;left:16px">
      <button onclick="S.screen='${S.token?'chat':'login'}';render()" style="background:none;border:1px solid var(--border);border-radius:12px;padding:4px 10px;font-size:12px;cursor:pointer;color:var(--text-muted);font-family:Cairo,sans-serif">${L('← الرئيسية','← Home')}</button>
    </div>
    <!-- Kareem greets the parent: a wave, then he settles into idle.
         MUTED deliberately -- greet.mp4's audio is "تمام، ممتاز، هيا بنا", which is
         addressed to a student starting a lesson and reads oddly to a parent. The
         gesture is what carries here, not the words. -->
    <div class="lp-hero-kareem" style="width:132px;margin:0 auto 14px">
      <video class="lp-kv kv-on" playsinline muted autoplay preload="auto"
             src="assets/kareem/greet.mp4"
             onended="this.src=kareemIdleSrc();this.loop=true;this.play().catch(function(){})"
             onerror="this.style.display='none'"></video>
    </div>
    <div class="auth-title">${L('لوحة متابعة ولي الأمر','Parent Dashboard')}</div>
    <div class="auth-subtitle">${L('تابع تقدّم طفلك. اطلب منه «كود ولي الأمر» من شاشة حسابه.','Track your child\'s progress. Ask them for their "Parent code" from their account screen.')}</div>
    <div id="parent-msg" class="error-msg" style="display:none"></div>
    <div class="form-group"><label class="form-label">${L('بريد حساب الطالب','Student account email')}</label>
      <input id="parent-email" class="form-input" type="email" placeholder="student@email.com"/></div>
    <div class="form-group"><label class="form-label">${L('كود ولي الأمر','Parent code')}</label>
      <input id="parent-code" class="form-input" type="text" placeholder="ABC123" style="text-transform:uppercase;letter-spacing:3px"/></div>
    <button class="btn btn-primary" id="b-parent-view" style="width:100%;margin-top:8px" onclick="doParentView()">${L('عرض التقدّم','View progress')}</button>
    <div id="parent-result" style="margin-top:18px"></div>
  </div>
</div>`;
}

async function doParentView() {
  const L = (ar, en) => S.lang === 'en' ? en : ar;
  const email = (ge('parent-email')?.value || '').trim();
  const code  = (ge('parent-code')?.value || '').trim().toUpperCase();
  const msg   = ge('parent-msg');
  const out   = ge('parent-result');
  const btn   = ge('b-parent-view');
  if (msg) msg.style.display = 'none';
  if (!email || !code) { if (msg) { msg.textContent = L('أدخل البريد والكود','Enter email and code'); msg.style.display='block'; } return; }
  if (btn) { btn.disabled = true; btn.textContent = L('جارٍ التحميل...','Loading...'); }
  try {
    const r = await fetch(API + '/parent/summary', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ email, code }) });
    const d = await r.json();
    if (!r.ok) throw new Error(d.error || 'Error');
    const fmtDate = (x) => x ? new Date(x).toLocaleDateString(S.lang==='en'?'en-GB':'ar-EG',{year:'numeric',month:'short',day:'numeric'}) : '—';
    const lastSeen = d.lastSeen ? new Date(d.lastSeen) : null;
    const ago = lastSeen ? Math.floor((Date.now()-lastSeen)/86400000) : null;
    const lastSeenTxt = lastSeen ? (ago<=0?L('اليوم','Today'):ago===1?L('أمس','Yesterday'):L(`منذ ${ago} يوم`,`${ago} days ago`)) : '—';
    const card = (label,val,color) => `<div style="background:var(--surface);border:1px solid var(--border);border-top:3px solid ${color};border-radius:12px;padding:14px;text-align:center"><div style="font-size:22px;font-weight:900;color:${color}">${val}</div><div style="font-size:11px;color:var(--text-muted);margin-top:3px">${label}</div></div>`;
    out.innerHTML = `
      <div style="text-align:center;font-weight:900;font-size:16px;margin-bottom:4px">${esc(d.name||'')}</div>
      <div style="text-align:center;font-size:12px;color:var(--text-muted);margin-bottom:14px">${esc(d.email||'')} ${d.plan==='pro'?'· ⭐ Pro':'· '+L('مجاني','Free')}</div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">
        ${card(L('إجمالي الأسئلة','Total questions'), d.totalQuestions||0, '#3B82F6')}
        ${card(L('أسئلة اليوم','Questions today'), d.dailyQuestions||0, '#F59E0B')}
        ${card(L('آخر نشاط','Last active'), lastSeenTxt, '#10B981')}
        ${card(L('انضمّ في','Joined'), fmtDate(d.joinedAt), '#8B5CF6')}
      </div>
      ${d.plan==='pro' && d.planExpiry ? `<div style="text-align:center;font-size:12px;color:var(--text-muted);margin-top:12px">${L('اشتراك Pro حتى','Pro until')} ${fmtDate(d.planExpiry)}</div>`:''}
      <div style="font-size:11px;color:var(--text-muted);text-align:center;margin-top:14px">${L('عرض للقراءة فقط — بموافقة الطالب عبر الكود.','Read-only view — granted by the student via the code.')}</div>`;
  } catch (e) {
    if (msg) { msg.textContent = L('بريد أو كود غير صحيح','Invalid email or code'); msg.style.display='block'; }
    out.innerHTML = '';
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = L('عرض التقدّم','View progress'); }
  }
}

function goTeacher() { S.screen = 'teacher'; render(); }

/* ── Teacher Dashboard (classes + roster) ── */
function tplTeacher() {
  const L = (ar, en) => S.lang === 'en' ? en : ar;
  const back = `<div style="position:absolute;top:16px;left:16px"><button onclick="S.screen='${S.token?'chat':'login'}';render()" style="background:none;border:1px solid var(--border);border-radius:12px;padding:4px 10px;font-size:12px;cursor:pointer;color:var(--text-muted);font-family:Cairo,sans-serif">${L('← الرئيسية','← Home')}</button></div>`;
  if (!S.token) {
    return `<div class="auth-screen"><div class="auth-card">${back}
      <div class="auth-logo">👩‍🏫</div>
      <div class="auth-title">${L('لوحة المعلّم','Teacher Dashboard')}</div>
      <div class="auth-subtitle">${L('سجّل الدخول لإنشاء فصل ومتابعة طلابك.','Sign in to create a class and track your students.')}</div>
      <button class="btn btn-primary" style="width:100%;margin-top:8px" onclick="goSignin()">${L('تسجيل الدخول','Sign in')}</button>
    </div></div>`;
  }
  return `<div class="auth-screen"><div class="auth-card" style="max-width:620px">${back}
    <div class="auth-logo">👩‍🏫</div>
    <div class="auth-title">${L('لوحة المعلّم','Teacher Dashboard')}</div>
    <div class="auth-subtitle">${L('أنشئ فصلاً، شارك الكود مع طلابك، وتابع نشاطهم.','Create a class, share the code with your students, and track their activity.')}</div>
    <div id="teacher-msg" class="error-msg" style="display:none"></div>

    <div class="form-group" style="margin-top:6px"><label class="form-label">${L('إنشاء فصل جديد','Create a new class')}</label>
      <input id="class-name" class="form-input" type="text" placeholder="${L('اسم الفصل (مثال: الصف 9 رياضيات)','Class name (e.g. Grade 9 Math)')}" style="width:100%;margin-bottom:8px"/>
      <button class="btn btn-primary" style="width:100%" onclick="createClass()">${L('إنشاء الفصل','Create class')}</button>
    </div>

    <div class="form-group"><label class="form-label">${L('الانضمام إلى فصل (للطلاب)','Join a class (students)')}</label>
      <input id="join-code" class="form-input" type="text" placeholder="${L('كود الفصل','Class code')}" style="width:100%;margin-bottom:8px;text-transform:uppercase;letter-spacing:3px"/>
      <button class="btn btn-secondary" style="width:100%" onclick="joinClass()">${L('انضمام','Join class')}</button>
    </div>

    <div id="teacher-classes" style="margin-top:18px;text-align:center;color:var(--text-muted)">${L('جارٍ التحميل...','Loading...')}</div>
  </div></div>`;
}

async function loadTeacherClasses() {
  const L = (ar, en) => S.lang === 'en' ? en : ar;
  const wrap = ge('teacher-classes');
  if (!wrap) return;
  try {
    const classes = await req('/teacher/classes');
    if (!Array.isArray(classes) || !classes.length) {
      wrap.innerHTML = `<div style="font-size:13px;color:var(--text-muted)">${L('لا توجد فصول بعد. أنشئ فصلاً للبدء.','No classes yet. Create one to get started.')}</div>`;
      return;
    }
    const fmtSeen = (x) => { if(!x) return '—'; const ago=Math.floor((Date.now()-new Date(x))/86400000); return ago<=0?L('اليوم','Today'):ago===1?L('أمس','Yesterday'):L(`منذ ${ago} يوم`,`${ago}d ago`); };
    wrap.innerHTML = classes.map(c => `
      <div style="background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:14px;margin-bottom:12px;text-align:${S.lang==='en'?'left':'right'}">
        <div style="display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap">
          <div style="font-weight:900;font-size:15px">${esc(c.name)}</div>
          <div style="font-size:12px;color:var(--text-muted)">${L('كود','Code')}: <code style="background:var(--bg);padding:3px 8px;border-radius:6px;letter-spacing:2px;font-weight:800;color:#F59E0B">${c.joinCode}</code>
            <button onclick="deleteClass('${c.id}')" title="delete" style="background:none;border:none;color:#EF4444;cursor:pointer;font-size:13px;margin-inline-start:6px">🗑</button></div>
        </div>
        <div style="font-size:12px;color:var(--text-muted);margin:8px 0 4px">${c.students.length} ${L('طالب','students')}</div>
        ${c.students.length ? `
        <table style="width:100%;border-collapse:collapse;font-size:13px">
          <tr style="color:var(--text-muted);font-size:11px;text-align:${S.lang==='en'?'left':'right'}">
            <th style="padding:4px">${L('الطالب','Student')}</th><th style="padding:4px">${L('الأسئلة','Questions')}</th><th style="padding:4px">${L('آخر نشاط','Last active')}</th><th style="padding:4px">${L('الخطة','Plan')}</th></tr>
          ${c.students.map(s=>`<tr style="border-top:1px solid var(--border)">
            <td style="padding:6px 4px;font-weight:700">${esc(s.name||'')}</td>
            <td style="padding:6px 4px">${s.totalQuestions||0}</td>
            <td style="padding:6px 4px;color:var(--text-muted)">${fmtSeen(s.lastSeen)}</td>
            <td style="padding:6px 4px">${s.plan==='pro'?'⭐':'·'}</td></tr>`).join('')}
        </table>` : `<div style="font-size:12px;color:var(--text-muted)">${L('شارك الكود مع طلابك للانضمام.','Share the code with students to join.')}</div>`}
      </div>`).join('');
  } catch (e) {
    wrap.innerHTML = `<div style="font-size:13px;color:#EF4444">${L('تعذّر التحميل','Could not load')}</div>`;
  }
}

async function createClass() {
  const name = (ge('class-name')?.value || '').trim();
  if (!name) return;
  try { await req('/teacher/class', 'POST', { name }); if(ge('class-name')) ge('class-name').value=''; loadTeacherClasses(); }
  catch (e) { showToast(e.message, 'error'); }
}

async function joinClass() {
  const code = (ge('join-code')?.value || '').trim().toUpperCase();
  if (!code) return;
  try { const d = await req('/teacher/join', 'POST', { code }); showToast((S.lang==='en'?'Joined ':'انضممت إلى ') + (d.className||''), 'success'); if(ge('join-code')) ge('join-code').value=''; loadTeacherClasses(); }
  catch (e) { showToast(S.lang==='en'?'Class not found':'الفصل غير موجود', 'error'); }
}

async function deleteClass(id) {
  try { await req('/teacher/class/' + id, 'DELETE'); loadTeacherClasses(); }
  catch (e) { showToast(e.message, 'error'); }
}

async function showParentCode() {
  const box = ge('parent-code-box');
  if (!box) return;
  if (!S.token) { showToast(S.lang==='en'?'Sign in first':'سجّل الدخول أولاً','error'); return; }
  box.textContent = '...';
  try {
    const d = await req('/parent/my-code');
    box.textContent = d.code || '——';
  } catch (e) {
    box.textContent = '——';
    showToast(S.lang==='en'?'Could not load code':'تعذّر تحميل الكود','error');
  }
}

