// Per-year international shelves (~0.8 MB) live in data/books-intl.js and are added to
// TEXTBOOK_DB the first time the book library opens (ensureIntlBooks).

function viewPDF(url, viewUrl, subj, title) {
  S.textbookUrl        = url;
  S.textbookViewUrl    = (viewUrl && viewUrl !== 'undefined' && viewUrl !== '') ? viewUrl : url;
  S.textbookActiveSubj = subj  || '';
  S.textbookActiveTitle= title || '';
  render();
}

