// English display names for the Arab-country curricula (international ones already have English labels).
const CUR_EN_NAME = {
  egypt:'🇪🇬 Egypt', egypt_ext:'🇪🇬 Egypt — Extra Books', egypt_lang:'🇪🇬 Egypt — Languages Schools', azhar:'🕌 Al-Azhar', saudi:'🇸🇦 Saudi Arabia', uae:'🇦🇪 UAE',
  kuwait:'🇰🇼 Kuwait', qatar:'🇶🇦 Qatar', bahrain:'🇧🇭 Bahrain', oman:'🇴🇲 Oman', jordan:'🇯🇴 Jordan',
  palestine:'🇵🇸 Palestine', lebanon:'🇱🇧 Lebanon', syria:'🇸🇾 Syria', iraq:'🇮🇶 Iraq', libya:'🇱🇾 Libya',
  sudan:'🇸🇩 Sudan', yemen:'🇾🇪 Yemen', morocco:'🇲🇦 Morocco', algeria:'🇩🇿 Algeria', tunisia:'🇹🇳 Tunisia',
  mauritania:'🇲🇷 Mauritania', other:'🌍 Other / General',
};
// Country/curriculum label in the active language (English name when in EN mode, else the Arabic label).
function curLabel(key) {
  const c = CURRICULA[key];
  const ar = c ? c.label : key;
  return (S.lang === 'en' && CUR_EN_NAME[key]) ? CUR_EN_NAME[key] : ar;
}

function tplLessons() {
  // Local bilingual helper that follows the APP language (S.lang), not the IGCSE hub language.
  const L = (en, ar) => S.lang === 'ar' ? ar : en;
  const curData   = CURRICULA[S.curriculum] || CURRICULA.egypt;
  const gradeData = (curData.grades && (curData.grades[S.grade] || curData.grades.high || Object.values(curData.grades)[0])) || { label:'', subjects:[] };
  const subjects  = gradeData.subjects || [];

  // ── VIEW: LESSON DETAIL ─────────────────────────────────────────────
  if (S.lessonView === 'lesson' && S.lessonSubject && S.lessonChapter) {
    const subj = S.lessonSubject;
    const chap = S.lessonChapter;
    const chapIdx = subj.topics.indexOf(chap);
    const chapNum = chapIdx + 1;
    const prevChap = chapIdx > 0 ? subj.topics[chapIdx - 1] : null;
    const nextChap = chapIdx < subj.topics.length - 1 ? subj.topics[chapIdx + 1] : null;
    const subjectEnc = encodeURIComponent(subj.name);
    const chapEnc    = encodeURIComponent(chap);

    const studyTools = [
      { id:'b-lesson-summary', icon:'📋', label:L('Smart summary','ملخص ذكي'),        desc:L('Concise explanation + key points','شرح مختصر + النقاط الأساسية'),   color:'#3B82F6', action:`openLessonTool('summary','${esc(subj.name)}','${esc(chap)}')` },
      { id:'b-lesson-quiz2',   icon:'📝', label:L('Short quiz','اختبار قصير'),     desc:L('Multiple choice + instant answers','أسئلة اختيار وإجابات فورية'),    color:'#8B5CF6', action:`openLessonTool('quiz','${esc(subj.name)}','${esc(chap)}')` },
      { id:'b-lesson-fc2',     icon:'🗂️', label:L('Flashcards','بطاقات تعليمية'), desc:L('Review with Q&A','مراجعة بطريقة السؤال والجواب'),  color:'#F59E0B', action:`openLessonTool('flashcards','${esc(subj.name)}','${esc(chap)}')` },
      { id:'b-lesson-ai2',     icon:'🤖', label:L('Ask AI','اسأل AI'),         desc:L('Open questions & detailed explanation','أسئلة مفتوحة والشرح التفصيلي'), color:'#10B981', action:`openLessonTool('chat','${esc(subj.name)}','${esc(chap)}')` },
      { id:'b-lesson-mm2',     icon:'🧠', label:L('Mind map','خريطة ذهنية'),     desc:L('Organize info visually','تنظيم المعلومات بصرياً'),        color:'#EC4899', action:`openLessonTool('mindmap','${esc(subj.name)}','${esc(chap)}')` },
      { id:'b-lesson-pdf2',    icon:'📥', label:L('PDF / Print','PDF / طباعة'),     desc:L('Export the summary to print','تصدير الملخص للطباعة'),          color:'#EF4444', action:`openLessonTool('pdf','${esc(subj.name)}','${esc(chap)}')` },
    ];

    return `
<div style="position:sticky;top:0;z-index:10;background:var(--bg);border-bottom:1px solid var(--border);padding:10px 14px;display:flex;align-items:center;gap:10px">
  <button onclick="S.lessonView='chapters';render()"
    style="background:var(--bg-card);border:1px solid var(--border);border-radius:10px;padding:7px 12px;cursor:pointer;font-size:18px;color:var(--primary);line-height:1">&#x2190;</button>
  <div style="flex:1;min-width:0">
    <div style="font-size:11px;color:var(--text-muted);font-weight:700">${esc(subj.icon)} ${esc(subj.name)}</div>
    <div style="font-size:14px;font-weight:900;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(chap)}</div>
  </div>
  <div style="font-size:11px;color:var(--text-muted);font-weight:700;white-space:nowrap">${chapNum}/${subj.topics.length}</div>
</div>
<div class="screen-body" style="padding-top:12px">

  <!-- ═══ CHAPTER INFO ═══ -->
  <div style="background:linear-gradient(135deg,${subj.color}18,${subj.color}08);border:1px solid ${subj.color}33;border-radius:16px;padding:16px;margin-bottom:16px">
    <div style="display:flex;align-items:center;gap:12px">
      <div style="width:48px;height:48px;border-radius:13px;background:${subj.color}30;display:flex;align-items:center;justify-content:center;font-size:24px;flex-shrink:0">${subj.icon}</div>
      <div style="flex:1;min-width:0">
        <div style="font-size:11px;color:${subj.color};font-weight:800;margin-bottom:3px">${L('Chapter','الفصل')} ${chapNum} ${L('of','من')} ${subj.topics.length}</div>
        <div style="font-size:16px;font-weight:900;color:var(--text)">${esc(chap)}</div>
        <div style="font-size:11px;color:var(--text-muted);margin-top:2px">${curLabel(S.curriculum)} · ${gradeData.label}</div>
      </div>
    </div>
  </div>

  <!-- ═══ AI EXPLANATION (primary, prominent) ═══ -->
  <div style="background:var(--bg-card);border:1.5px solid var(--primary);border-radius:16px;padding:18px;margin-bottom:18px;box-shadow:0 6px 24px #7C3AED22">
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:14px">
      <div style="font-size:16px;font-weight:900;color:var(--text)">🤖 ${L('AI explanation','شرح الدرس بالذكاء الاصطناعي')}</div>
      ${S.lessonContent ? `<button class="btn btn-primary btn-sm" id="b-gen-lesson" style="font-size:12px">${S.lessonLoading ? (S.lessonProgress || L('⏳ Loading...','⏳ جارٍ...')) : L('🔄 Regenerate','🔄 تجديد')}</button>` : ''}
    </div>
    ${S.lessonContent ? `
    <div style="line-height:2.1;font-size:16px;max-height:65vh;overflow-y:auto;padding-left:4px">${md(S.lessonContent)}</div>
    <div style="display:flex;gap:8px;margin-top:14px;flex-wrap:wrap">
      <button class="btn btn-primary btn-sm" id="b-lesson-teacher" style="background:#8B5CF6;border-color:#8B5CF6">🎬 ${L(teacher().name.en + ' on the board', teacher().name.ar + ' على السبورة')}</button>
      <button class="btn btn-secondary btn-sm" id="b-lesson-chat">💬 ${L('Discuss in chat','ناقش في المحادثة')}</button>
      <button class="btn btn-secondary btn-sm" id="b-lesson-fc">🗂️ ${L('Cards','بطاقات')}</button>
      <button class="btn btn-secondary btn-sm" id="b-lesson-quiz">📝 ${L('Quiz','اختبار')}</button>
    </div>` : `
    <div style="text-align:center;padding:14px 0">
      <div style="font-size:46px;margin-bottom:10px">🤖</div>
      <div style="font-size:14px;color:var(--text-muted);margin-bottom:18px;line-height:1.8">${L('Get a full, simple explanation of this chapter — with examples and practice questions.','احصل على شرح كامل ومبسّط لهذا الفصل — مع أمثلة وأسئلة تطبيقية.')}</div>
      <button class="btn btn-primary" id="b-gen-lesson" style="width:100%;max-width:440px;font-size:17px;font-weight:900;padding:16px 12px">
        ${S.lessonLoading ? (S.lessonProgress || L('⏳ Loading...','⏳ جارٍ...')) : L('✨ Explain this chapter','✨ اشرح لي هذا الفصل')}
      </button>
    </div>`}
  </div>

  <!-- ═══ STUDY TOOLS (compact, below the explanation) ═══ -->
  <div style="font-size:11px;color:var(--text-muted);font-weight:800;letter-spacing:1px;text-transform:uppercase;margin-bottom:10px">⚡ ${L('Study tools','أدوات المذاكرة')}</div>
  <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:20px">
    ${studyTools.map(tool => `
    <button id="${tool.id}" onclick="${tool.action}"
      style="display:flex;flex-direction:column;align-items:center;gap:4px;padding:10px 6px;
             background:${tool.color}14;border:1px solid ${tool.color}33;border-radius:12px;
             cursor:pointer;font-family:Cairo,sans-serif;transition:.18s"
      onmouseover="this.style.background='${tool.color}25';this.style.transform='translateY(-2px)'"
      onmouseout="this.style.background='${tool.color}14';this.style.transform=''">
      <div style="font-size:20px;line-height:1">${tool.icon}</div>
      <div style="font-size:11px;font-weight:800;color:${tool.color}">${tool.label}</div>
    </button>`).join('')}
  </div>

  <!-- ═══ EXTERNAL RESOURCES ═══ -->
  <div style="background:var(--bg-card);border:1px solid var(--border);border-radius:16px;padding:16px;margin-bottom:16px">
    <div style="font-size:13px;font-weight:900;color:var(--text);margin-bottom:10px">🌐 ${L('External resources','مصادر خارجية')}</div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">
      ${[
        { icon:'▶️', name:'YouTube', color:'#FF0000', url:`https://www.youtube.com/results?search_query=${chapEnc}+${subjectEnc}+شرح` },
        { icon:'📐', name:'Khan Academy', color:'#14BF96', url:`https://ar.khanacademy.org/search?page_search_query=${chapEnc}` },
        { icon:'📖', name:L('Student book','كتاب الطالب'), color:'#3B82F6', url:'javascript:void(0)', onclick:`S.screen='textbook';S.textbookUrl='home';render()` },
        { icon:'🌍', name:'Wikipedia', color:'#3366CC', url:`https://ar.wikipedia.org/wiki/${chapEnc}` },
      ].map(r=>`
      <button onclick="${r.onclick || `window.open('${r.url}','_blank')`}"
        style="display:flex;align-items:center;gap:8px;padding:10px 12px;background:${r.color}10;border:1px solid ${r.color}30;border-radius:12px;cursor:pointer;font-family:Cairo,sans-serif;text-align:right;width:100%">
        <span style="font-size:18px">${r.icon}</span>
        <span style="font-size:12px;font-weight:800;color:var(--text)">${r.name}</span>
        <span style="margin-right:auto;color:${r.color};font-size:11px">←</span>
      </button>`).join('')}
    </div>
  </div>

  <!-- ═══ NAVIGATION ═══ -->
  <div style="display:flex;gap:8px">
    ${prevChap ? `
    <button onclick="S.lessonChapter='${esc(prevChap)}';S.lessonContent='';S.lessonLoading=false;render()"
      style="flex:1;padding:11px;border-radius:12px;border:1px solid var(--border);background:var(--bg-card);
             color:var(--text);font-family:Cairo,sans-serif;font-size:12px;font-weight:800;cursor:pointer;text-align:right">
      &#x2190; ${esc(prevChap).slice(0,20)}${esc(prevChap).length>20?'...':''}
    </button>` : '<div style="flex:1"></div>'}
    ${nextChap ? `
    <button onclick="S.lessonChapter='${esc(nextChap)}';S.lessonContent='';S.lessonLoading=false;render()"
      style="flex:1;padding:11px;border-radius:12px;border:none;background:linear-gradient(135deg,${subj.color},${subj.color}cc);
             color:#fff;font-family:Cairo,sans-serif;font-size:12px;font-weight:800;cursor:pointer;text-align:left">
      ${esc(nextChap).slice(0,20)}${esc(nextChap).length>20?'...':''} &#x2192;
    </button>` : ''}
  </div>

</div>`;
  }

  // ── VIEW: CHAPTERS ───────────────────────────────────────────────────
  if (S.lessonView === 'chapters' && S.lessonSubject) {
    const subj = S.lessonSubject;
    // Track which chapters the user visited
    const doneKey = `oa_chap_done_${S.curriculum}_${subj.name}`;
    let doneChs = {};
    try { doneChs = JSON.parse(localStorage.getItem(doneKey)||'{}'); } catch {}
    const doneCnt = Object.keys(doneChs).length;
    const pct = Math.round((doneCnt / subj.topics.length) * 100);
    return `
<div style="position:sticky;top:0;z-index:10;background:var(--bg);border-bottom:1px solid var(--border);padding:10px 14px;display:flex;align-items:center;gap:10px">
  <button onclick="S.lessonView='subjects';S.lessonSubject=null;render()"
    style="background:var(--bg-card);border:1px solid var(--border);border-radius:10px;padding:7px 12px;cursor:pointer;font-size:18px;color:var(--primary);line-height:1">&#x2190;</button>
  <div style="flex:1">
    <div style="font-size:15px;font-weight:900;color:var(--text)">${subj.icon} ${esc(subj.name)}</div>
    <div style="font-size:10px;color:var(--text-muted)">${curLabel(S.curriculum)} · ${gradeData.label}</div>
  </div>
  <div style="text-align:center;min-width:42px">
    <div style="font-size:14px;font-weight:900;color:${subj.color}">${pct}%</div>
    <div style="font-size:9px;color:var(--text-muted)">${L('done','مكتمل')}</div>
  </div>
</div>
<div class="screen-body" style="padding-top:12px">

  <!-- Progress bar -->
  <div style="background:var(--border);border-radius:999px;height:8px;margin-bottom:16px;overflow:hidden">
    <div style="width:${pct}%;height:100%;background:linear-gradient(90deg,${subj.color},${subj.color}99);border-radius:999px;transition:.6s"></div>
  </div>

  <!-- Quick subject tools -->
  <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:20px">
    ${[
      { icon:'💬', label:L('Ask AI','اسأل AI'), color:'#10B981', action:`openLessonTool('chat','${esc(subj.name)}','')` },
      { icon:'📋', label:L('Summary','ملخص'), color:'#3B82F6', action:`openLessonTool('summary','${esc(subj.name)}','')` },
      { icon:'📝', label:L('Quiz','اختبار'), color:'#8B5CF6', action:`openLessonTool('quiz','${esc(subj.name)}','')` },
      { icon:'🗂️', label:L('Cards','بطاقات'), color:'#F59E0B', action:`openLessonTool('flashcards','${esc(subj.name)}','')` },
      { icon:'📚', label:L('Book','كتاب'), color:'#6366F1', action:`S.screen='textbook';S.textbookUrl='home';S.textbookSubjFilter='${esc(subj.name)}';S.textbookViewUrl=null;render()` },
    ].map(t=>`
    <button onclick="${t.action}"
      style="display:flex;flex-direction:column;align-items:center;gap:6px;padding:12px 4px;background:${t.color}14;
             border:1.5px solid ${t.color}33;border-radius:14px;cursor:pointer;font-family:Cairo,sans-serif;transition:.15s"
      onmouseover="this.style.background='${t.color}25'" onmouseout="this.style.background='${t.color}14'">
      <span style="font-size:22px">${t.icon}</span>
      <span style="font-size:11px;font-weight:800;color:${t.color}">${t.label}</span>
    </button>`).join('')}
  </div>

  <!-- Chapters List -->
  <div style="font-size:11px;font-weight:800;color:var(--text-muted);letter-spacing:1px;margin-bottom:10px">📋 ${L('Curriculum chapters','فصول المنهج')} — ${subj.topics.length} ${L('chapters','فصل')}</div>
  <div style="display:flex;flex-direction:column;gap:8px">
    ${subj.topics.map((topic, idx) => {
      const done = doneChs[idx] ? true : false;
      return `
    <button class="lesson-chapter-btn" data-topic-idx="${idx}"
      style="display:flex;align-items:center;gap:12px;padding:14px 16px;background:var(--bg-card);
             border:1.5px solid ${done ? subj.color+'55' : 'var(--border)'};
             border-radius:14px;cursor:pointer;text-align:right;width:100%;font-family:Cairo,sans-serif;transition:.2s"
      onmouseover="this.style.borderColor='${subj.color}';this.style.background='${subj.color}08'"
      onmouseout="this.style.borderColor='${done ? subj.color+'55' : 'var(--border)'}';this.style.background='var(--bg-card)'">
      <div style="width:38px;height:38px;border-radius:11px;background:${done ? subj.color : subj.color+'22'};
                  display:flex;align-items:center;justify-content:center;
                  font-size:${done?'18':'13'}px;font-weight:900;color:${done?'#fff':subj.color};flex-shrink:0">
        ${done ? '✓' : idx+1}
      </div>
      <div style="flex:1;text-align:right;min-width:0">
        <div style="font-size:14px;font-weight:800;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(topic)}</div>
        <div style="font-size:10px;color:var(--text-muted);margin-top:2px">${L('Chapter','الفصل')} ${idx+1}${done?(S.lang==='en'?' · ✅ Reviewed':' · ✅ تمت المراجعة'):''}</div>
      </div>
      <span class="lesson-board-btn" data-topic-idx="${idx}" title="${S.lang==='en' ? teacher().name.en + ' on the board' : teacher().name.ar + ' على السبورة'}"
        style="flex-shrink:0;background:#8B5CF6;color:#fff;font-size:12px;font-weight:800;border-radius:10px;padding:7px 11px;font-family:Cairo,sans-serif;white-space:nowrap;cursor:pointer">
        🎬 ${S.lang==='en'?'Explain':'اشرح'}
      </span>
      <div style="display:flex;flex-direction:column;align-items:flex-end;gap:4px;flex-shrink:0">
        <span style="color:${subj.color};font-size:16px">&#x2190;</span>
      </div>
    </button>`}).join('')}
  </div>

</div>`;
  }

  // ── VIEW: SUBJECTS (default) ─────────────────────────────────────────
  return `
<div class="screen-header">
  <div class="screen-title">📚 ${S.lang==='en'?'Study Hub':'المذاكرة'}</div>
  <div style="font-size:11px;color:var(--text-muted)">${curLabel(S.curriculum)} · ${gradeData.label}</div>
</div>
<div class="screen-body">

  ${['igcse','cambridge_olevel','cambridge_alevel','oxford_aqa','german_abitur','edexcel','aqa','ocr','american','ib','cbse','icse','french_bac','australian','canadian','south_africa'].includes(S.curriculum) ? `
  <div style="background:#3B82F611;border:1px solid #3B82F633;border-radius:10px;padding:10px 14px;margin-bottom:12px;font-size:12px;display:flex;gap:8px;align-items:flex-start">
    <span style="font-size:16px">ℹ️</span>
    <span style="color:var(--text-muted);line-height:1.7">${L('Content is based on the latest available official curriculum.','المحتوى مبني على أحدث إصدار متاح من المنهج الرسمي.')} <b style="color:var(--primary)">${L('Subject & topic codes verified ✅','أكواد المواد والموضوعات مُدققة ✅')}</b></span>
  </div>` : ''}

  <!-- Country & Grade Selector (big dropdowns) -->
  <div style="background:var(--bg-card);border:1px solid var(--border);border-radius:var(--radius);padding:14px;margin-bottom:12px;display:grid;gap:12px">
    <div>
      <div style="font-size:12px;font-weight:800;color:var(--text-muted);margin-bottom:6px">🌍 ${L('Choose country / curriculum','اختر الدولة / المنهج')}</div>
      <select onchange="homeUpdateCountry(this.value)"
        style="width:100%;padding:14px 16px;border-radius:12px;border:1.5px solid var(--primary);background:var(--bg);color:var(--text);font-size:15px;font-weight:800;font-family:Cairo,sans-serif;cursor:pointer">
        ${visibleCurricula().map(([k,v])=>`<option value="${k}" ${S.curriculum===k?'selected':''}>${curLabel(k)}</option>`).join('')}
      </select>
    </div>
    <div>
      <div style="font-size:12px;font-weight:800;color:var(--text-muted);margin-bottom:6px">🎓 ${L('Choose grade / stage','اختر المرحلة الدراسية')}</div>
      <select onchange="try{localStorage.setItem('ctx_chosen','1')}catch(e){}; homeUpdateGrade(this.value)"
        style="width:100%;padding:14px 16px;border-radius:12px;border:1.5px solid var(--primary);background:var(--bg);color:var(--text);font-size:15px;font-weight:800;font-family:Cairo,sans-serif;cursor:pointer">
        ${Object.entries(curData.grades).map(([k,v])=>`<option value="${k}" ${S.grade===k?'selected':''}>${v.label}</option>`).join('')}
      </select>
    </div>
  </div>

  <!-- Subjects Grid (or Book-Library redirect for books-only curricula like كتب خارجية) -->
  ${subjects.length ? `
  <div style="font-size:13px;font-weight:800;color:var(--text-muted);margin-bottom:10px">📚 ${L('Choose subject','اختر المادة الدراسية')}</div>
  <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:12px">
    ${subjects.map(s=>`
    <button class="lesson-subj-btn" data-subj-idx="${subjects.indexOf(s)}"
      style="display:flex;flex-direction:column;align-items:center;gap:10px;padding:20px 12px;background:var(--bg-card);border:1.5px solid var(--border);border-radius:16px;cursor:pointer;font-family:Cairo,sans-serif;transition:.2s;position:relative"
      onmouseover="this.style.borderColor='${s.color}';this.style.background='${s.color}11'" onmouseout="this.style.borderColor='var(--border)';this.style.background='var(--bg-card)'">
      <div style="width:56px;height:56px;border-radius:16px;background:${s.color}22;display:flex;align-items:center;justify-content:center;font-size:28px">${s.icon}</div>
      <div style="font-size:13px;font-weight:900;color:var(--text);text-align:center">${esc(s.name)}</div>
      <div style="font-size:10px;color:var(--text-muted)">${s.topics.length} ${L('chapters','فصل')}</div>
      <div style="position:absolute;top:8px;left:8px;width:6px;height:6px;border-radius:50%;background:${s.color}"></div>
    </button>`).join('')}
  </div>` : `
  <div style="background:var(--bg-card);border:1px solid var(--border);border-radius:16px;padding:24px;text-align:center;margin-top:8px">
    <div style="font-size:40px;margin-bottom:10px">📚</div>
    <div style="font-size:15px;font-weight:900;color:var(--text);margin-bottom:6px">${L('This is a book library','هذه مكتبة كتب')}</div>
    <div style="font-size:13px;color:var(--text-muted);line-height:1.9;margin-bottom:16px;max-width:420px;margin-left:auto;margin-right:auto">${L('This selection contains downloadable books (El-Moasser, Archive.org…) rather than lessons. Open the Book Library to browse them.','هذا الاختيار يحتوي على كتب للتحميل (المعاصر، Archive.org…) وليس دروساً. افتح مكتبة الكتب لتصفح الكتب الخارجية.')}</div>
    <button onclick="S.screen='textbook';render()" class="btn btn-primary" style="font-size:15px;font-weight:900;padding:14px 24px">📚 ${L('Open Book Library','افتح مكتبة الكتب')}</button>
  </div>`}

</div>`;
  return `
<div class="screen-header"><div class="screen-title">\u{1F4D6} الدروس</div></div>
<div class="screen-body">

  ${['igcse','cambridge_olevel','cambridge_alevel','oxford_aqa','german_abitur','edexcel','aqa','ocr','american','ib','cbse','icse','french_bac','australian','canadian','south_africa'].includes(S.curriculum) ? `
  <div style="background:#3B82F611;border:1px solid #3B82F633;border-radius:10px;padding:10px 14px;margin-bottom:12px;font-size:12px;display:flex;gap:8px;align-items:flex-start">
    <span style="font-size:16px">ℹ️</span>
    <span style="color:var(--text-muted);line-height:1.7">
      المحتوى مبني على أحدث إصدار متاح من المنهج الرسمي.
      للتحقق من آخر التحديثات يُنصح بمراجعة الموقع الرسمي للجهة.
      <br><b style="color:var(--primary)">أكواد المواد والموضوعات الرئيسية مُدققة ✅</b>
    </span>
  </div>` : ''}
  <div style="background:var(--bg-card);border:1px solid var(--border);border-radius:var(--radius);padding:16px;margin-bottom:12px">
    <div style="font-size:12px;font-weight:800;color:var(--text-muted);margin-bottom:10px">\u{1F30D} اختر الدولة / المنهج</div>
    <div style="display:flex;flex-wrap:wrap;gap:6px">
      ${visibleCurricula().map(([k,v])=>`
      <button class="curriculum-btn" data-curriculum="${k}"
        style="padding:6px 12px;border-radius:20px;
               border:1.5px solid ${S.curriculum===k?'var(--primary)':'var(--border)'};
               background:${S.curriculum===k?'var(--primary)':'transparent'};
               color:${S.curriculum===k?'#fff':'var(--text)'};
               font-family:Cairo,sans-serif;font-size:11px;font-weight:700;cursor:pointer;transition:.2s">
        ${v.label}
      </button>`).join('')}
    </div>
  </div>

  <div style="background:var(--bg-card);border:1px solid var(--border);border-radius:var(--radius);padding:16px;margin-bottom:12px">
    <div style="font-size:12px;font-weight:800;color:var(--text-muted);margin-bottom:10px">\u{1F393} اختر المرحلة الدراسية</div>
    <div style="display:flex;flex-wrap:wrap;gap:8px">
      ${Object.entries(curData.grades).map(([k,v])=>`
      <button class="grade-btn" data-grade="${k}"
        style="padding:9px 18px;border-radius:12px;
               border:1.5px solid ${S.grade===k?'var(--primary)':'var(--border)'};
               background:${S.grade===k?'var(--primary)':'transparent'};
               color:${S.grade===k?'#fff':'var(--text)'};
               font-family:Cairo,sans-serif;font-size:13px;font-weight:800;cursor:pointer;transition:.2s">
        ${{primary:'\u{1F3EB}',middle:'\u{1F4DA}',high:'\u{1F393}',high1:'\u{1F393}',high_med:'\u{1F3E5}',high_eng:'\u{1F3D7}',high_biz:'\u{1F4BC}',high_arts:'\u{1F4D6}'}[k]||'\u{1F393}'} ${v.label}
      </button>`).join('')}
    </div>
    <div style="font-size:11px;color:var(--text-muted);margin-top:8px">
      \u{1F4CC} <b style="color:var(--primary)">${curData.label}</b>
      &nbsp;—&nbsp;<b style="color:#22C55E">${gradeData.label}</b>
      &nbsp;—&nbsp;${subjects.length} مادة دراسية
    </div>
  </div>

  <!-- AI Lessons Section -->
  <div style="background:linear-gradient(135deg,#1E293B,#253047);border:1px solid var(--primary)44;border-radius:var(--radius);padding:16px;margin-bottom:20px">
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px">
      <div>
        <div style="font-weight:900;font-size:15px">\u{1F916} دروس بالذكاء الاصطناعي</div>
        <div style="font-size:12px;color:var(--text-muted);margin-top:2px">يولّد AI دروساً مخصصة لمادة ${esc(S.subject)} — ${gradeData.label}</div>
      </div>
      <button class="btn btn-primary btn-sm" id="b-ai-lessons" onclick="loadAILessons()">توليد الآن</button>
    </div>
    <div id="ai-lessons-box"></div>
  </div>


</div>`;
}
/* â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
   AUTH LOGIC
   â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â• */
async function doLogin() {
  const email = ge('f-email')?.value?.trim();
  const pass  = ge('f-pass')?.value;
  if (!email || !pass) { showAuthErr('يرجى ملء جميع الحقول'); return; }
  setBtnLoading('b-login', 'جارٍ الدخول...');
  try {
    const d = await req('/auth/login', 'POST', { email, password: pass });
    S.token = d.token; S.user = d.user; saveLocal();
    S.screen = 'home'; render(); showToast(S.lang==='en'?'Welcome back 👋':'أهلاً بعودتك 👋', 'success');
  } catch(e) {
    // If regular login fails, try school account login
    try {
      const SERVER = 'https://ostazai-server-production.up.railway.app';
      const r = await fetch(SERVER + '/api/school/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password: pass }),
      });
      const sd = await r.json();
      if (r.ok && sd.token) {
        localStorage.setItem('school_token', sd.token);
        localStorage.setItem('school_user',  JSON.stringify(sd.user));
        localStorage.setItem('school_info',  JSON.stringify(sd.school));
        window.location.href = '/school-portal.html';
        return;
      }
    } catch(_) {}
    showAuthErr(e.message);
  }
  finally { setBtnLoading('b-login', 'دخول'); }
}

async function doRegister() {
  const name    = ge('f-name')?.value?.trim();
  const email   = ge('f-email')?.value?.trim();
  const pass    = ge('f-pass')?.value;
  const country = ge('f-country')?.value;
  const refCode = ge('f-ref')?.value?.trim().toUpperCase() || '';
  if (!name || !email || !pass) {
    showAuthErr('يرجى ملء جميع الحقول المطلوبة'); return;
  }
  setBtnLoading('b-register', 'جارٍ الإنشاء...');
  try {
    const deviceId = await getDeviceFingerprint();
    const body = { name, email, password: pass, country, deviceId };
    if (refCode) body.referralCode = refCode;
    const d = await req('/auth/register', 'POST', body);
    S.token = d.token; S.user = d.user;
    S.curriculum = country in CURRICULA ? country : 'egypt';
    saveLocal();
    let msg;
    if (d.trialBlocked) {
      msg = '✅ تم إنشاء الحساب — النسخة المجانية (تم استخدام التجربة من هذا الجهاز مسبقاً)';
    } else if (refCode) {
      msg = 'تم إنشاء الحساب + 7 أيام Pro هدية! 🎉';
    } else {
      msg = 'تم إنشاء الحساب + 7 أيام Pro مجاناً! 🎉';
    }
    S.screen = 'home'; render(); showToast(msg, d.trialBlocked ? 'info' : 'success');
  } catch(e) { showAuthErr(e.message); }
  finally { setBtnLoading('b-register', 'إنشاء حساب 🚀'); }
}

