function setLoadingMsg(msg) {
  const el = ge('loading-msg');
  if (el) el.textContent = msg;
}

async function init() {
  // Safety: force login screen after 8 seconds no matter what
  const safetyTimer = setTimeout(() => {
    if (S.screen === 'loading') {
      S.token = null; S.user = null;
      S.screen = 'login';
      render();
    }
  }, 8000);

  try {
    loadLocal();
    document.body.classList.toggle('light', S.darkMode);
    applyLangDir();
    S.screen = 'loading'; render();

    setLoadingMsg('جارٍ التحقق من حسابك...');
    await new Promise(r => setTimeout(r, 400));

    if (S.token) {
      try {
        setLoadingMsg('جارٍ تحميل بياناتك...');
        const d = await Promise.race([
          req('/auth/me'),
          new Promise((_, rej) => setTimeout(() => rej(new Error('timeout')), 5000))
        ]);
        S.user = d.user || d;
        setLoadingMsg('مرحباً بك! 👋');
        await new Promise(r => setTimeout(r, 300));
        S.screen = localStorage.getItem('oa_onboarded') ? 'home' : 'onboarding';
      } catch {
        S.token = null; S.user = null;
        S.screen = 'login';
      }
    } else if (S.user && (S.user.id || S.user._id || S.user.email)) {
      // A real account with an expired/absent token still goes to the app.
      S.screen = 'home';
    } else {
      // Guests land on the landing page every visit, not just their first.
      // Older builds persisted oa_user as {} for guests. An empty object is
      // truthy, so this branch used to send every returning visitor straight
      // past the landing -- meaning it was seen once per browser, ever, taking
      // the pricing, SEO copy and Mr. Kareem's introduction with it.
      if (S.user) {
        S.user = null;
        try { localStorage.removeItem('oa_user'); } catch (_) {}
      }
      S.screen = 'login';
    }

    render();
  } catch(e) {
    console.error('Init error:', e);
    S.screen = 'login';
    render();
  } finally {
    clearTimeout(safetyTimer);
  }

  const urlParams = new URLSearchParams(window.location.search);

  // Handle PWA shortcut ?screen=xxx
  if (urlParams.get('screen') && S.token) {
    const targetScreen = urlParams.get('screen');
    const validScreens = ['chat','lessons','flashcards','quiz','summary','mindmap','stats','notes','bookmarks','profile','upgrade'];
    if (validScreens.includes(targetScreen)) {
      S.screen = targetScreen;
      history.replaceState({}, '', window.location.pathname);
      render();
    }
  }

  // Handle referral link ?ref=CODE
  if (urlParams.get('ref') && !S.token) {
    S.screen = 'register';
    render();
    // Don\'t clear the URL yet — bind() will read it to pre-fill the field
  }

  // Handle password reset link
  if (urlParams.get('reset')) {
    S.resetToken = urlParams.get('reset');
    history.replaceState({}, '', window.location.pathname);
    S.screen = 'reset-password';
    render();
    return;
  }

  // Handle payment gateway redirects
  if (urlParams.get('payment') === 'success') {
    const gateway = urlParams.get('gateway') || '';
    const token   = urlParams.get('token') || '';  // PayPal order token
    const checkoutId = urlParams.get('checkout_id') || '';  // Polar checkout id
    history.replaceState({}, '', window.location.pathname);

    setTimeout(async () => {
      showToast('🎉 تم الدفع بنجاح! جارٍ تفعيل Pro...', 'success');

      // PayPal: capture the order
      if (gateway === 'paypal' && token && S.token) {
        try {
          await req('/billing/capture-paypal-order', 'POST', { orderId: token });
        } catch(e) { console.warn('PayPal capture:', e.message); }
      }

      // Polar: verify the checkout directly (webhook-independent activation)
      if (gateway === 'polar' && checkoutId && S.token) {
        try {
          await req('/billing/polar-verify', 'POST', { checkoutId });
        } catch(e) { console.warn('Polar verify:', e.message); }
      }

      // Refresh user after 3s (allow webhook to process)
      setTimeout(async () => {
        try {
          const d = await req('/auth/me');
          S.user = d.user || d;
          saveLocal();
          render();
          if (S.user?.plan === 'pro') {
            showToast('⭐ تم تفعيل Pro بنجاح!', 'success');
          }
        } catch(e) {}
      }, 3000);
    }, 500);
  }
  if (urlParams.get('payment') === 'cancelled') {
    history.replaceState({}, '', window.location.pathname);
    setTimeout(() => showToast('❌ تم إلغاء عملية الدفع', 'error'), 500);
  }

  // Sync XP every 5 minutes
  setInterval(syncXP, 5 * 60 * 1000);
  // Auto-refresh leaderboard every 2 minutes (only if on that screen)
  setInterval(() => { if (S.screen === 'leaderboard') loadLeaderboard(); }, 2 * 60 * 1000);
  // Each of these is independent, and a throw in one used to abort the rest of init().
  // That is exactly how Android lost its study timer for months, so they are isolated.
  [initPushNotifications, initStudyTimer].forEach(fn => {
    try { fn(); } catch (e) { console.warn('[init]', fn.name, 'failed:', e && e.message); }
  });

  // Network status monitoring
  function updateNetworkBanner() {
    const banner = ge('offline-banner');
    if (!banner) return;
    if (!navigator.onLine) {
      banner.style.display = 'block';
      document.body.style.paddingTop = '36px';
    } else {
      if (banner.style.display !== 'none') {
        banner.style.display = 'none';
        document.body.style.paddingTop = '';
        showToast('✅ عاد الاتصال بالإنترنت', 'success');
      }
    }
  }
  window.addEventListener('online',  updateNetworkBanner);
  window.addEventListener('offline', updateNetworkBanner);
  updateNetworkBanner(); // Check immediately

  // PWA install prompt
  window.addEventListener('beforeinstallprompt', e => {
    e.preventDefault();
    window._pwaPrompt = e;
    // Show banner if currently on home screen, or fire event for next render
    const banner = ge('pwa-banner');
    if (banner) banner.style.display = 'block';
    window.dispatchEvent(new Event('_pwaready'));
  });
}

init();

